import numpy as np, statsmodels.api as sm, pandas as pd
z=np.load('cache.npz'); B=z['B']; Bres=z['Bres']; yr=z['yr']; ypr=z['ypr']; D=z['D']; Dres=np.load('Dres.npy')
bm=lambda v:(B*v[:,None]).sum(0)/np.maximum(B.sum(0),1)
def res(v):
    b=bm(v); return (v-B@b)+Bres@b
H={}
def getH(psi):
    key=round(psi,2)
    if key not in H: H[key]=res(np.maximum(D-psi,0))
    return H[key]
def fitk(psi,yv):
    return sm.OLS(yv,sm.add_constant(np.column_stack([Dres,getH(psi)]))).fit(cov_type='HC1')
grid=np.arange(7,16.01,0.1)
ssr=np.array([fitk(p,yr).ssr for p in grid])
print("best psi",round(grid[ssr.argmin()],2))
print(pd.DataFrame({'psi':grid.round(1),'ssr':(ssr-ssr.min()).round(1)}).iloc[::2].to_string(index=False))
m=fitk(10.0,yr); print(m.summary().tables[1]); print("slope<10:",round(m.params[1],4),"slope>10:",round(m.params[1]+m.params[2],4))
